-- =============================================================================
-- 0004 — Starter Island missions 4–24
--
-- Apply to a database seeded before these missions existed:
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 -f database/migrations/0004_starter_island_missions.sql
-- (or paste the file into the Neon SQL Editor). Fresh installs get the same
-- content from seed.sql. Runs in one transaction and refuses to run twice.
--
-- Adds 21 published levels (starter-04 … starter-24), each with its own
-- environment, map, scene, checkpoints, objectives and hints, and the unlock
-- chain starter-N ← starter-(N-1). Canyon Circuit already requires the whole
-- Starter Island world (WORLD_COMPLETED), so it now opens after mission 24.
-- =============================================================================
BEGIN;

DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM levels WHERE slug = 'starter-04') THEN
    RAISE EXCEPTION '0004 already applied (starter-04 exists)';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM levels WHERE slug = 'starter-03') THEN
    RAISE EXCEPTION '0004 needs the seeded Starter Island (starter-03 is missing)';
  END IF;
END $$;


