SELECT l.id, g.name, 1
  FROM (VALUES
    ('starter-04', 'Finish Two Corners'),
    ('starter-05', 'Finish Basic Navigation'),
    ('starter-06', 'Finish Collect the Beacon'),
    ('starter-07', 'Finish Avoid the Rocks'),
    ('starter-08', 'Finish Bridge Crossing'),
    ('starter-09', 'Finish Sensor Basics'),
    ('starter-10', 'Finish River Crossing'),
    ('starter-11', 'Finish Distance Sensor'),
    ('starter-12', 'Finish Follow the Path'),
    ('starter-13', 'Finish Obstacle Detection'),
    ('starter-14', 'Finish Precision Parking'),
    ('starter-15', 'Finish Multi-Sensor Control'),
    ('starter-16', 'Finish Route Planning'),
    ('starter-17', 'Finish Signal Crossing'),
    ('starter-18', 'Finish Rescue Route'),
    ('starter-19', 'Finish Energy Station'),
    ('starter-20', 'Finish Autonomous Navigation'),
    ('starter-21', 'Finish Complex Route'),
    ('starter-22', 'Finish Rescue Supplies'),
    ('starter-23', 'Finish Emergency Route'),
    ('starter-24', 'Finish Final Navigation')
  ) AS g(level_slug, name)
  JOIN levels l ON l.slug = g.level_slug;

