INSERT INTO environments (id, name, kind, theme, description, config, status) VALUES
  ('starter-meadow-lanes', 'Meadow Lanes', 'LEVEL', 'starter', 'Hedge-lined lanes zigzagging across a flower meadow to the meadow shed.', '{"lighting":"daylight"}'::jsonb, 'PUBLISHED'),
  ('starter-beacon-field', 'Beacon Field', 'LEVEL', 'starter', 'An open field track with three signal beacons and a tall signal tower.', '{"lighting":"daylight"}'::jsonb, 'PUBLISHED'),
  ('starter-boulder-woods', 'Boulder Woods', 'LEVEL', 'starter', 'A forest lane blocked by fallen boulders, with a woodcutter’s gate at the end.', '{"lighting":"daylight"}'::jsonb, 'PUBLISHED'),
  ('starter-log-bridge', 'Log Bridge', 'LEVEL', 'starter', 'A narrow log bridge over a forest stream leading to a camp.', '{"lighting":"daylight"}'::jsonb, 'PUBLISHED'),
  ('starter-ranger-hut', 'Ranger Hut', 'LEVEL', 'starter', 'A log-lined forest path ending at the ranger’s hut.', '{"lighting":"daylight"}'::jsonb, 'PUBLISHED'),
  ('starter-ferry-landing', 'Ferry Landing', 'LEVEL', 'starter', 'A river bridge and bank road to the ferry shed.', '{"lighting":"daylight"}'::jsonb, 'PUBLISHED'),
  ('starter-river-docks', 'River Docks', 'LEVEL', 'starter', 'A boardwalk along the river docks with jetties and a boat house.', '{"lighting":"daylight"}'::jsonb, 'PUBLISHED'),
  ('starter-stepping-stones', 'Stepping Stones', 'LEVEL', 'starter', 'A stepped path down the river bank to the old water mill.', '{"lighting":"daylight"}'::jsonb, 'PUBLISHED'),
  ('starter-harbour-spiral', 'Harbour Spiral', 'LEVEL', 'starter', 'A harbour boardwalk that spirals inward to the lighthouse.', '{"lighting":"daylight"}'::jsonb, 'PUBLISHED'),
  ('starter-boat-dock', 'Boat Dock', 'LEVEL', 'starter', 'A jetty with a narrow mooring bay between moored boats.', '{"lighting":"daylight"}'::jsonb, 'PUBLISHED'),
  ('starter-sensor-lab', 'Sensor Lab', 'LEVEL', 'starter', 'A robotics lab floor with racks, painted turn lines and a radar dish.', '{"lighting":"daylight","chase":{"back":2,"height":2.8,"side":0.9}}'::jsonb, 'PUBLISHED'),
  ('starter-facility-yard', 'Facility Yard', 'LEVEL', 'starter', 'Three aisles of racks and scanner gates in the facility yard.', '{"lighting":"daylight","chase":{"back":2,"height":2.8,"side":0.9}}'::jsonb, 'PUBLISHED'),
  ('starter-signal-crossing', 'Signal Crossing', 'LEVEL', 'starter', 'A crossing with coloured signal tiles and a control tower.', '{"lighting":"daylight"}'::jsonb, 'PUBLISHED'),
  ('starter-rescue-depot', 'Rescue Depot', 'LEVEL', 'starter', 'A lane around the rescue depot with a helipad.', '{"lighting":"daylight"}'::jsonb, 'PUBLISHED'),
  ('starter-energy-spiral', 'Energy Spiral', 'LEVEL', 'starter', 'A canyon path spiralling out past an old mine to an energy station.', '{"lighting":"warmAfternoon"}'::jsonb, 'PUBLISHED'),
  ('starter-canyon-switchbacks', 'Canyon Switchbacks', 'LEVEL', 'starter', 'Winding switchbacks between sandstone walls up to a lookout.', '{"lighting":"warmAfternoon"}'::jsonb, 'PUBLISHED'),
  ('starter-gorge-run', 'Gorge Run', 'LEVEL', 'starter', 'Zigzags down the canyon, a steel bridge over the gorge and a gate.', '{"lighting":"warmAfternoon"}'::jsonb, 'PUBLISHED'),
  ('starter-supply-outpost', 'Supply Outpost', 'LEVEL', 'starter', 'An outpost lane with three supply bays, tents and a gate.', '{"lighting":"coolDaylight"}'::jsonb, 'PUBLISHED'),
  ('starter-fallen-trees', 'Fallen Trees', 'LEVEL', 'starter', 'A storm-hit outpost road with trunks lying across it.', '{"lighting":"coolDaylight"}'::jsonb, 'PUBLISHED'),
  ('starter-guide-line', 'Guide Line', 'LEVEL', 'starter', 'A painted guide line through the research outpost to the dome.', '{"lighting":"coolDaylight"}'::jsonb, 'PUBLISHED'),
  ('starter-rescue-arena', 'Rescue Arena', 'LEVEL', 'starter', 'The Starter Island arena: grandstands, signal tiles and the rescue pad.', '{"lighting":"goldenGorge"}'::jsonb, 'PUBLISHED');
